-- 20261027_missing_summon_items.sql
--
-- Authors the 51 missing SummonItem/SummonItemIntoBag targets referenced by
-- PEQ spells (spells referenced item ids that were never present in items).
-- Numeric values are cloned from each item's closest existing family row;
-- live stat data was not obtainable (Allakhazam item pages return stripped
-- stubs from this box, and live item ids diverge from PEQ ids for PEQ-authored
-- ranges). Names follow the family pattern and, where verified, Allakhazam
-- (Exigent Servant/Minion line, Greater Adventure/Gadget Pack, Witness
-- Protection Pack, Stomples Package, Wayfarer's Tonic/Wine, Essence of the
-- Elements, Mystrae's Favor clicky line). Wedding-set content names are
-- contextual placeholders and safe to rename.
--
-- NOT included: the 10 Spellcaster's Empowering Essence items (36251-36256,
-- 36260-36263). Live pet empowerment has no stock EQEmu path (pets cannot
-- equip items; feeding consumes them without effect), so wiring worneffect
-- there would be dead data until a pet-empower C++ change exists.
--
-- Enchant Feymetal / Mass Enchant Feymetal (27664/27665) summoned item 1139
-- 'Blue Resistance Stone'; the correct bar already exists as 81139
-- 'Enchanted Feymetal Bar'. Repointed below.
--
-- Apply: mysql -h127.0.0.1 -ueqemu -p peq < this_file
-- After: restart zones (items load at zone boot). No client file export needed.
--




















































-- Enchant Feymetal: correct bar exists at 81139
UPDATE spells_new SET effect_base_value1 = 81139 WHERE id IN (27664,27665) AND effect_base_value1 = 1139;
